inline int Clip(const std::string&name){for(unsigned i=0;i<sizeof(Clips)/sizeof(Clips[0]);++i)if(name==Clips[i])return int(i);return -1;}
inline bool Pose(int clip,unsigned edge,const std::string&name,const std::array<float,3>&mix,UnityBody::M&out){
 if(clip<0||unsigned(clip)>=sizeof(Clips)/sizeof(Clips[0])||edge>1)return false;
 for(unsigned i=0;i<sizeof(Names)/sizeof(Names[0]);++i)if(name==Names[i]){const float*p=Values[unsigned(clip)*2+edge][i];for(unsigned r=0;r<3;++r)for(unsigned c=0;c<3;++c)out.r[r][c]=p[r*3+c];out.t={};for(unsigned k=0;k<8;++k){double w=1;for(unsigned axis=0;axis<3;++axis)w*=k&(1<<axis)?mix[axis]:1-mix[axis];out.t=UnityBody::Add(out.t,UnityBody::Scale({p[9+k*3],p[10+k*3],p[11+k*3]},w));}return true;}return false;
}
inline bool Reference(const UnityGame::Actor&source,int clip,unsigned edge,UnityGame::Actor&out){out=source;out.animationFrame=-1;for(unsigned i=0;i<15;++i)if(!Pose(clip,edge,UnityGame::Names[i],source.complection,out.poses[i]))return false;for(auto&a:out.attachments)if(UnityWeaponCatalog::Assembly(a.name)&&!Pose(clip,edge,a.name,source.complection,a.pose))return false;return true;}
